/**
 * Write the Visuals gallery's generated files from the notes (2026-11-23):
 *   src/lib/gallery/galleryIndex.generated.ts     subjects + one lazy loader each
 *   src/lib/gallery/galleryNav.generated.ts       exam -> first subject (the header)
 *   src/lib/gallery/subjects/<route>.generated.ts that subject's visuals (VISUALS) and
 *                                                 their tile pictures as static markup
 *                                                 (THUMBS), served apart by the thumbs route
 *
 *   npm run gallery:index              # regenerate
 *   npm run gallery:index -- --check   # exit 1 if any committed file is stale
 *
 * RUN AFTER SHIPPING OR CHANGING A NOTES CHAPTER OR DIAGRAM (beside
 * notes:chapter-loaders); tests/gallery-index.test.ts fails until you do.
 *
 * Why the pictures are generated, not drawn per request: a page drawing a
 * diagram to static markup would import every diagram (the ebooks' registry);
 * a generated file per subject holds only that subject's 5-100 pictures.
 */
import { existsSync, readdirSync, readFileSync, unlinkSync, writeFileSync } from "node:fs";
import path from "node:path";
import { renderDiagramMarkup } from "@/lib/ebooks/diagrams";
import type { VisualizationSlug } from "@/app/notes/_types";
import { buildGalleryIndex } from "@/lib/gallery/build";
import { galleryBuildInputs, galleryNavOf, gallerySubjectsOf } from "@/lib/gallery/buildInputs";

const ROOT = path.resolve(__dirname, "../../src/lib/gallery");
const HEAD = "// GENERATED by `npm run gallery:index` from the notes registry. Do not edit.\n// Why: scripts/gallery/gen-index.ts. Drift check: tests/gallery-index.test.ts.\n";

function main() {
  const check = process.argv.includes("--check");
  const { chapters, opts } = galleryBuildInputs();
  const visuals = buildGalleryIndex(chapters, opts);
  const subjects = gallerySubjectsOf(visuals);
  const files = new Map<string, string>();

  files.set(
    path.join(ROOT, "galleryIndex.generated.ts"),
    `${HEAD}import type { GallerySubject, GalleryVisual } from "./gallery";\n\n` +
      `export const GALLERY_SUBJECTS: readonly GallerySubject[] = ${JSON.stringify(subjects, null, 2)};\n\n` +
      `export const GALLERY_LOADERS: Record<string, () => Promise<{ VISUALS: readonly GalleryVisual[]; THUMBS: Readonly<Record<string, string>> }>> = {\n` +
      subjects.map((s) => `  ${JSON.stringify(s.subjectRoute)}: () => import("./subjects/${s.subjectRoute}.generated"),\n`).join("") +
      `};\n`
  );
  files.set(
    path.join(ROOT, "galleryNav.generated.ts"),
    `${HEAD}// Exam -> its first subject with visuals: all the header's Visuals link reads.\n\n` +
      `export const GALLERY_NAV: Readonly<Record<string, string>> = ${JSON.stringify(galleryNavOf(visuals), null, 2)};\n`
  );
  for (const s of subjects) {
    const own = visuals.filter((v) => v.subjectRoute === s.subjectRoute);
    // One entry per line: a changed diagram is a one-line diff, and no indent padding.
    const visualLines = own.map((v) => `  ${JSON.stringify(v)},
`).join("");
    const thumbLines = [...new Set(own.map((v) => v.slug))]
      .map((slug) => `  ${JSON.stringify(slug)}: ${JSON.stringify(renderDiagramMarkup(slug as VisualizationSlug))},
`)
      .join("");
    files.set(
      path.join(ROOT, "subjects", `${s.subjectRoute}.generated.ts`),
      `${HEAD}import type { GalleryVisual } from "../gallery";

` +
        `export const VISUALS: readonly GalleryVisual[] = [
${visualLines}];

` +
        `/** Each visual's tile picture: the diagram drawn as static markup, as the ebooks draw it. */
` +
        `export const THUMBS: Readonly<Record<string, string>> = {
${thumbLines}};
`
    );
  }

  // A subject that lost all its visuals leaves a stale file behind: remove it.
  const keep = new Set(files.keys());
  const stale = readdirSync(path.join(ROOT, "subjects"))
    .map((f) => path.join(ROOT, "subjects", f))
    .filter((f) => f.endsWith(".generated.ts") && !keep.has(f));

  if (check) {
    const drift = [...files].filter(([f, body]) => !existsSync(f) || readFileSync(f, "utf8") !== body).map(([f]) => f);
    if (drift.length || stale.length) {
      console.error(`gallery files are stale: ${[...drift, ...stale].map((f) => path.relative(process.cwd(), f)).join(", ")}. Run npm run gallery:index`);
      process.exit(1);
    }
    console.log(`gallery files up to date: ${visuals.length} visuals in ${subjects.length} subjects`);
    return;
  }
  for (const [f, body] of files) writeFileSync(f, body);
  for (const f of stale) unlinkSync(f);
  console.log(`wrote ${files.size} files: ${visuals.length} visuals in ${subjects.length} subjects${stale.length ? `, removed ${stale.length} stale` : ""}`);
}

main();
